import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"腾讯混元学习地图","description":"混元（Tencent Hy）是腾讯的模型与开放能力，不是元宝，也不是 CodeBuddy。本目录只教怎么认模型、怎么在 TokenHub 上调 Hy3、怎么找到开源权重。","frontmatter":{"title":"腾讯混元学习地图","description":"混元（Tencent Hy）是腾讯的模型与开放能力，不是元宝，也不是 CodeBuddy。本目录只教怎么认模型、怎么在 TokenHub 上调 Hy3、怎么找到开源权重。","domain":"product","tags":["hunyuan","llm-api"],"role":"map"},"headers":[],"relativePath":"zh/products/hunyuan/index.md","filePath":"zh/products/hunyuan/index.md","lastUpdated":1787110548000}'),d={name:"zh/products/hunyuan/index.md"};function s(o,t,l,h,c,p){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="腾讯混元学习地图" tabindex="-1">腾讯混元学习地图 <a class="header-anchor" href="#腾讯混元学习地图" aria-label="Permalink to &quot;腾讯混元学习地图&quot;">​</a></h1><blockquote><p><strong>混元 / Tencent Hy</strong> 是腾讯自研的大模型家族，以及把这些模型开放给开发者的通道。官网定义自己是「全链路自研」的模型与研究站（<a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>）。云上调用走 <a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">TokenHub</a>。</p><p>本目录<strong>只写模型与开放能力</strong>。元宝、CodeBuddy、WorkBuddy、ima 是同厂其它产品，只在下面家族图占一行。</p></blockquote><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>好几个腾讯入口都带「混元」或「Hy」。它们<strong>不是</strong>同一个产品的四张皮。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯 AI（与混元相关的官方一级）</span></span>
<span class="line"><span>├── 混元 / Hy — 模型、研究、开源（本目录主线）</span></span>
<span class="line"><span>│   ├── Hy 模型（Hy3、Hy-MT2、生图 / 生视频 / 生 3D / 视觉理解 / ASR）</span></span>
<span class="line"><span>│   ├── 研究（Hy3 技术帖、Hyra 等）</span></span>
<span class="line"><span>│   ├── Co-design / International（官网栏目，不是独立调用面）</span></span>
<span class="line"><span>│   ├── 试用 Hy（Hy AI Studio）</span></span>
<span class="line"><span>│   └── 开源权重（GitHub Tencent-Hunyuan / Hugging Face tencent/Hy3）</span></span>
<span class="line"><span>├── TokenHub — 云上模型网关（调混元，也卖第三方模型）</span></span>
<span class="line"><span>├── 腾讯混元大模型（云产品 1729，老 API 树）</span></span>
<span class="line"><span>├── 元宝 — C 端助手（接入了 Hy3）          → issue #76</span></span>
<span class="line"><span>├── CodeBuddy — 编码 IDE / CLI               → issue #78</span></span>
<span class="line"><span>├── WorkBuddy — 办公 Agent</span></span>
<span class="line"><span>└── ima — 知识管家</span></span></code></pre></div><table tabindex="0"><thead><tr><th>入口</th><th>是什么</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>Hy 模型 / 混元官网</strong></td><td>模型与研究主站</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a></td><td>本页 + <a href="./hunyuan.html">教程</a></td></tr><tr><td><strong>TokenHub</strong></td><td>统一大模型 API（混元 + 第三方）</td><td><a href="https://cloud.tencent.com/product/tokenhub" target="_blank" rel="noreferrer">产品页</a> / <a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">文档 1823</a></td><td><a href="./hunyuan.html">教程</a> / <a href="./hunyuan-cookbook.html">Cookbook</a> / <a href="./hunyuan-cheatsheet.html">速查</a></td></tr><tr><td>试用 Hy（AI Studio）</td><td>网页里试用对话 / 多模态</td><td><a href="https://aistudio.tencent.com/" target="_blank" rel="noreferrer">aistudio.tencent.com</a></td><td>教程一节，不拆页</td></tr><tr><td>开源权重</td><td>Hy3 等 Apache-2.0 权重与部署脚本</td><td><a href="https://github.com/Tencent-Hunyuan" target="_blank" rel="noreferrer">Tencent-Hunyuan</a> / <a href="https://huggingface.co/tencent/Hy3" target="_blank" rel="noreferrer">tencent/Hy3</a></td><td>教程一节 + 速查</td></tr><tr><td>研究</td><td>技术帖与论文</td><td><a href="https://hunyuan.tencent.com/research" target="_blank" rel="noreferrer">research</a> / <a href="https://hy.tencent.com/research/hy3" target="_blank" rel="noreferrer">Hy3 帖</a></td><td>地图一行</td></tr><tr><td>Co-design / International</td><td>官网一级栏目</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> 页头</td><td>地图一行；不是新产品</td></tr><tr><td>腾讯混元大模型（1729）</td><td>更早的云 API 产品树</td><td><a href="https://cloud.tencent.com/product/hunyuan" target="_blank" rel="noreferrer">product/hunyuan</a> / <a href="https://cloud.tencent.com/document/product/1729" target="_blank" rel="noreferrer">文档 1729</a></td><td>地图一行。Hy3 正文以 TokenHub 为准</td></tr><tr><td>元宝</td><td>全能 AI 助手，已接入 Hy3</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td>地图一行，正文见 #76</td></tr><tr><td>CodeBuddy</td><td>腾讯云代码助手</td><td><a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a></td><td>地图一行，正文见 #78</td></tr><tr><td>WorkBuddy</td><td>办公 Agent 工作台</td><td><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a> / <a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noreferrer">云产品页</a></td><td>地图一行，不写教程</td></tr><tr><td>ima</td><td>以知识库为基础的 AI 知识管家</td><td><a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a></td><td>地图一行，不写教程</td></tr><tr><td>招聘 / 人脸识别 / 云主机 / 短信</td><td>官网或腾讯云一级 nav 里的非本主题项</td><td>—</td><td><strong>非本站</strong></td></tr></tbody></table><p><strong>容易撞名的几条</strong>（展开见 <a href="./hunyuan-glossary.html">术语表</a>）：</p><ul><li><strong>混元 / Hy ≠ 元宝</strong>。混元是模型；元宝是 C 端助手。</li><li><strong>Hy3 ≠ TokenHub ≠ AI Studio</strong>。模型、网关、试用台是三件事。</li><li><strong>没有官方 <code>hunyuan</code> CLI</strong>。终端里写代码的是 CodeBuddy，不是本目录。</li><li><strong>开源仓库名 ≠ TokenHub 的 <code>model</code> 参数</strong>。例如权重 <code>HunyuanImage-3.0</code> 对 API slug <code>hy-image-v3.0</code>。</li></ul><h3 id="快速决策-我该走哪扇门" tabindex="-1">快速决策：我该走哪扇门？ <a class="header-anchor" href="#快速决策-我该走哪扇门" aria-label="Permalink to &quot;快速决策：我该走哪扇门？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在网页里先试试 Hy3 / 翻译 / 多模态</span></span>
<span class="line"><span>│   └── → Hy AI Studio（aistudio.tencent.com）或官网「试用 Hy」</span></span>
<span class="line"><span>├── 在自己的前端 / Node 服务里调混元</span></span>
<span class="line"><span>│   └── → TokenHub，model = hy3（本目录主线）</span></span>
<span class="line"><span>├── 把 Hy3 接到 Claude Code / Cursor 等现成 coding agent</span></span>
<span class="line"><span>│   └── → TokenHub「接入 AI 工具」；Hy3 示例见官方 1823/131903</span></span>
<span class="line"><span>│       └── 不要在本目录找 CodeBuddy 教程（那是 #78）</span></span>
<span class="line"><span>├── 本机 / 自建集群跑开源权重</span></span>
<span class="line"><span>│   └── → github.com/Tencent-Hunyuan/Hy3（官方写的是 8 卡级 GPU）</span></span>
<span class="line"><span>├── 只要聊天、搜索、写文档，不写代码</span></span>
<span class="line"><span>│   └── → 元宝（#76），不是本目录</span></span>
<span class="line"><span>├── 要 IDE 补全 / 仓库 Agent</span></span>
<span class="line"><span>│   └── → CodeBuddy（#78），不是混元 CLI</span></span>
<span class="line"><span>└── 云主机 / 对象存储 / 短信</span></span>
<span class="line"><span>    └── → 非本站。不要在混元文档里找</span></span></code></pre></div><p>来源：<a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>、<a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">TokenHub 文档</a>、<a href="https://cloud.tencent.com/document/product/1823/132252" target="_blank" rel="noreferrer">混元调用指南</a>。</p><h2 id="什么时候值得看这套文档" tabindex="-1">什么时候值得看这套文档 <a class="header-anchor" href="#什么时候值得看这套文档" aria-label="Permalink to &quot;什么时候值得看这套文档&quot;">​</a></h2><p><strong>值得看</strong></p><ul><li>你要在 TypeScript / Node 里用 OpenAI 兼容 SDK 调一个国内模型，官方推荐入口是 TokenHub，slug 是 <code>hy3</code>。</li><li>你已经在用 Claude Code / Cursor，想换成或兼用 Hy3（官方有接入页）。</li><li>你要对照开源权重和托管 API，而不是再装一个腾讯编码 IDE。</li></ul><p><strong>先别看</strong></p><ul><li>你要的是元宝那种聊天 App —— 去 #76。</li><li>你要的是 CodeBuddy 的补全和仓库 Agent —— 去 #78。</li><li>你想搞懂 MoE / MTP / 注意力为什么这样设计 —— 去 <a href="./../../tech/fundamentals/LLM.html">LLM 基础</a> 和 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。本目录不写模型内部。</li></ul><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读</th><th>目标</th></tr></thead><tbody><tr><td>1. 认门</td><td>本页家族图</td><td>不再把元宝 / TokenHub / Hy3 当成同一个东西</td></tr><tr><td>2. 调通</td><td><a href="./hunyuan.html">教程</a></td><td>15 分钟内用 TokenHub 打出第一句 <code>hy3</code></td></tr><tr><td>3. 接到工作流</td><td><a href="./hunyuan-cookbook.html">Cookbook</a></td><td>流式、思考档、Function Calling、Claude Code</td></tr><tr><td>4. 查参数</td><td><a href="./hunyuan-cheatsheet.html">速查表</a></td><td>slug、价格、端点、数据源</td></tr><tr><td>5. 分清名字</td><td><a href="./hunyuan-glossary.html">术语表</a></td><td>两套官方页谁说了算</td></tr></tbody></table><h2 id="模型速查-只列官方已给-slug-的混元系" tabindex="-1">模型速查（只列官方已给 slug 的混元系） <a class="header-anchor" href="#模型速查-只列官方已给-slug-的混元系" aria-label="Permalink to &quot;模型速查（只列官方已给 slug 的混元系）&quot;">​</a></h2><p>完整表以 <a href="https://cloud.tencent.com/document/product/1823/130051" target="_blank" rel="noreferrer">TokenHub 模型列表</a> 为准。价格只抄 <a href="https://cloud.tencent.com/document/product/1823/130055" target="_blank" rel="noreferrer">模型价格</a>（2026-08-14）。</p><table tabindex="0"><thead><tr><th>官方名</th><th><code>model</code></th><th>窗口（入 / 出）</th><th>一句话（官方）</th></tr></thead><tbody><tr><td>Hy3</td><td><code>hy3</code></td><td>192k / 128k（窗口 256k）</td><td>「基于真实业务场景打磨……强化 Coding、长文、推理和 Agent」</td></tr><tr><td>Hy3 preview</td><td><code>hy3-preview</code></td><td>同上</td><td>官方标注 <strong>2026-08-31 下线</strong>，不要当默认</td></tr><tr><td>Hy-MT2-Pro / Plus / Lite</td><td><code>hy-mt2-pro</code> 等</td><td>4k / 4k</td><td>翻译专项</td></tr><tr><td>Hy-Role / Latest</td><td><code>hy-role</code> / <code>hunyuan-role-latest</code></td><td>28k / 4k</td><td>角色扮演</td></tr><tr><td>HY-Image-V3.0</td><td><code>hy-image-v3.0</code></td><td>—</td><td>文生图 / 图生图</td></tr><tr><td>HY-3D-3.1</td><td><code>hy-3d-3.1</code></td><td>—</td><td>文生 3D / 图生 3D</td></tr></tbody></table><p>Hy3 托管价：输入 <strong>1</strong> / 输出 <strong>4</strong> / 缓存命中 <strong>0.25</strong> 元/百万 tokens。开源权重是另一条线，见 <a href="./hunyuan.html#开源权重">教程 · 开源</a>。</p><h2 id="本目录不写什么" tabindex="-1">本目录不写什么 <a class="header-anchor" href="#本目录不写什么" aria-label="Permalink to &quot;本目录不写什么&quot;">​</a></h2><ul><li>元宝、CodeBuddy、WorkBuddy、ima 的完整教程。</li><li>TokenHub 上的 DeepSeek / Kimi / GLM 选型（那是网关能力，不是混元）。</li><li>腾讯云非 AI 产品（CVM、COS、短信、域名）。</li><li>模型内部训练与推理机制。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./hunyuan.html">教程</a> — 试用、第一次 API、开源入口</li><li><a href="./hunyuan-cookbook.html">Cookbook</a></li><li><a href="./hunyuan-cheatsheet.html">速查表</a></li><li><a href="./hunyuan-glossary.html">术语表</a></li><li><a href="./../../tech/fundamentals/LLM.html">LLM 基础</a></li><li><a href="./../ai-coding/">产品总览</a></li></ul>`,26)])])}const m=e(d,[["render",s]]);export{b as __pageData,m as default};
